    public boolean valueEqual(str _singleValue, str _conditionValue)
    {
        boolean ret = false;

        ttsbegin;
        matchingTmpTable.clear();
        matchingTmpTable.StringValue = _singleValue;
        matchingTmpTable.insert();
        ttscommit;

        Query q = new Query();
        QueryBuildDataSource qbds = q.addDataSource(tableNum(GUPMatchingTmpTable));
        QueryBuildRange qbr = qbds.addRange(fieldNum(GUPMatchingTmpTable, StringValue));
        qbr.value(_conditionValue);
        QueryRun qr = new QueryRun(q);
        qr.setRecord(matchingTmpTable);

        if (qr.next())
        {
            //matchingTmpTable = qr.get(tableNum(GUPMatchingTmpTable));
            //if (matchingTmpTable.StringValue == singleValue)
            //{
                ret = true;
            //}
        }

        return ret;
    }

